const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const Card = ({ hidden }) => {
  const [count, setCount] = useState(1);
  const [picked, setPicked] = useState(false);

  return (
    <article className={picked ? 'card card--picked' : 'card'}>
      <h3 className="card__title">오버사이즈 셔츠</h3>
      <p className="card__state">{count}개 · {picked ? '담김' : '안 담김'}</p>
      <div className="row">
        <button className="up" type="button" onClick={() => setCount((c) => c + 1)}>+1</button>
        <button className="pick" type="button" onClick={() => setPicked(true)}>담기</button>
      </div>
    </article>
  );
};

const App = () => {
  const [hidden, setHidden] = useState(false);

  return (
    <div>
      <Card hidden={hidden} />
      <div className="controls">
        <button className="hide" type="button" onClick={() => setHidden(true)}>감추기</button>
        <button className="show" type="button" onClick={() => setHidden(false)}>보이기</button>
      </div>
    </div>
  );
};

root.render(<App />);

